var addSlotGame=function(n){return{onUpdateDisplayName:function(t){n("#GameName")[0].value=t.replaceAll(" ","").toLowerCase()},submitForm:function(){n.ajax({method:"POST",url:"/GameSettings/CloneSlotGame",data:n("#cloneForm").serialize()}).done(function(n){n?alert(n):window.location.href="/GameSettings"})},onChangeGameType:function(){const t=n("#GameType").val();n.ajax({method:"GET",url:"/games?type="+t}).done(function(t){var r=n("#SelectedGame"),i;n(r).empty();for(i in t)t.hasOwnProperty(i)&&n(r).append(n(`<option value="${t[i].value}">${t[i].text}</option>`))})}}}(jQuery);